// SPDX-License-Identifier: MIT
//! sin and cos as glibc computes them on x86-64 Linux, for the arguments
//! the DCT twiddle factors use.
//!
//! `sin` and `cos` are correctly rounded (evaluated in f128). glibc's
//! results are within one unit in the last place of that and almost always
//! equal to it; the angles where they differ are listed in
//! `glibc_exceptions.zig`, generated by running glibc. `glibcSin` and
//! `glibcCos` apply those corrections.

const std = @import("std");
const exceptions = @import("glibc_exceptions.zig").entries;

const pio2: f128 = 1.57079632679489661923132169163975144209858469968755291048747;

fn seriesSin(r: f128) f128 {
    const r2 = r * r;
    var term: f128 = r;
    var sum: f128 = r;
    var k: u32 = 2;
    while (k < 80) : (k += 2) {
        term = -term * r2 / @as(f128, @floatFromInt(k * (k + 1)));
        sum += term;
        if (@abs(term) <= 0x1p-120 * @abs(sum)) break;
    }
    return sum;
}

fn seriesCos(r: f128) f128 {
    const r2 = r * r;
    var term: f128 = 1;
    var sum: f128 = 1;
    var k: u32 = 1;
    while (k < 80) : (k += 2) {
        term = -term * r2 / @as(f128, @floatFromInt(k * (k + 1)));
        sum += term;
        if (@abs(term) <= 0x1p-120 * @abs(sum)) break;
    }
    return sum;
}

/// Correctly rounded sine, for |x| up to about 1e6.
pub fn sin(x: f64) f64 {
    return eval(x, 0);
}

/// Correctly rounded cosine, for |x| up to about 1e6.
pub fn cos(x: f64) f64 {
    return eval(x, 1);
}

fn eval(x: f64, shift: u2) f64 {
    if (x == 0) return if (shift == 0) x else 1;
    const xq: f128 = x;
    const q = @round(xq / pio2);
    const r = xq - q * pio2;
    const qi: i64 = @intFromFloat(q);
    const m: u2 = @truncate(@as(u64, @bitCast(qi)) +% shift);
    const v: f128 = switch (m) {
        0 => seriesSin(r),
        1 => seriesCos(r),
        2 => -seriesSin(r),
        3 => -seriesCos(r),
    };
    return @floatCast(v);
}

pub const Entry = struct { arg: u64, cos: bool, delta: i8 };

fn correction(x: f64, is_cos: bool) i64 {
    const key: u64 = @bitCast(x);
    var lo: usize = 0;
    var hi: usize = exceptions.len;
    while (lo < hi) {
        const mid = (lo + hi) / 2;
        const e = exceptions[mid];
        if (e.arg < key or (e.arg == key and !e.cos and is_cos)) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    if (lo < exceptions.len and exceptions[lo].arg == key and exceptions[lo].cos == is_cos) return exceptions[lo].delta;
    return 0;
}

fn adjust(v: f64, d: i64) f64 {
    if (d == 0) return v;
    const bits: i64 = @bitCast(v);
    return @bitCast(bits +% d);
}

/// glibc's `sin` for the twiddle angles.
pub fn glibcSin(x: f64) f64 {
    return adjust(sin(x), correction(x, false));
}

/// glibc's `cos` for the twiddle angles.
pub fn glibcCos(x: f64) f64 {
    return adjust(cos(x), correction(x, true));
}

test "glibc corrections apply" {
    for (exceptions) |e| {
        const x: f64 = @bitCast(e.arg);
        const plain = if (e.cos) cos(x) else sin(x);
        const fixed = if (e.cos) glibcCos(x) else glibcSin(x);
        try std.testing.expectEqual(@as(i64, @as(i64, @bitCast(plain)) + e.delta), @as(i64, @bitCast(fixed)));
    }
    try std.testing.expectEqual(@as(f64, 1), cos(0));
    try std.testing.expectEqual(@as(f64, 0), sin(0));
}
